function Extract-Docx($docxPath, $outDir) {
    if (Test-Path $outDir) { Remove-Item -Recurse -Force $outDir }
    [System.IO.Compression.ZipFile]::ExtractToDirectory($docxPath, $outDir)
    $xml = Get-Content -Path "$outDir\word\document.xml" -Raw -Encoding utf8
    $text = [System.Text.RegularExpressions.Regex]::Replace($xml, '<[^>]+>', "`n")
    Set-Content -Path "$outDir\text.txt" -Value $text -Encoding utf8
}

