449: void BSP_Audio_Poll(void)
450: {
451:     uint32_t now = HAL_GetTick();
452: 
453:     /* 1. 收取应答字节 */
454:     while (s_rx_tail != s_rx_head)
455:     {
456:         uint8_t b = s_rx_ring[s_rx_tail];
457:         s_rx_tail = (uint16_t)((s_rx_tail + 1U) % AUDIO_RX_RING_SIZE);
458:         audio_rx_parse(b);
459:     }
460: 
461:     /* 2. 上电 5s 静默期：期间只收不发 */
462:     if (!s_ready)
463:     {
464:         if ((now - s_power_on_tick) >= AUDIO_POWER_ON_WAIT_MS)
465:         {
466:             s_ready        = 1U;
467:             s_last_tx_tick = now - AUDIO_CMD_GAP_MS;   /* 立刻允许发第一条 */
468:             audio_req_push(AOP_FLASH, 0U);             /* 初始化后先切到 SPI-FLASH 盘符 */
469:             /* 预设默认硬件音量 (5/10 -> 15/30) */
470:             audio_req_push(AOP_VOL, (uint8_t)((uint16_t)5U * AUDIO_VOL_HW_MAX / AUDIO_VOL_UI_MAX));
471:         }
472:         return;
473:     }
474: 
475:     /* 3. 停止合并窗口到期：确实没有新的播放请求，才真正下发 STOP */
476:     if ((s_halt_pending != 0U) && ((now - s_halt_tick) >= AUDIO_HALT_HOLD_MS))
477:     {
478:         s_halt_pending = 0U;
479:         if (audio_req_has(AOP_PLAY) == 0U)
480:         {
481:             s_q_count = 0U;
482:             s_q_idx   = 0U;
483:             audio_req_push(AOP_STOP, 0U);
484:         }
485:     }
486: 
487:     /* 4. 每 500ms 最多发一条待发指令 */
