void Algo_Breath_StepGuide(uint32_t dt_ms, uint8_t target_bpm, BreathGuideOut_t *out)
{
    uint32_t cycle_ms;
    uint32_t inhale_ms;
    uint32_t exhale_ms;

    if (out == NULL) return;
    memset(out, 0, sizeof(*out));

    if (s_phase == BREATH_PHASE_IDLE)
