229: static void audio_req_push(uint8_t type, uint16_t arg)
230: {
231:     taskENTER_CRITICAL();
232:     if (s_req_cnt == 0U)
233:     {
234:         s_req[s_req_tail].type = type;
235:         s_req[s_req_tail].arg  = arg;
236:         s_req_tail = (uint8_t)((s_req_tail + 1U) % AUDIO_FIFO_MAX);
237:         s_req_cnt  = 1U;
238:     }
239:     else if (s_req_cnt < AUDIO_FIFO_MAX)
240:     {
241:         s_req[s_req_tail].type = type;
242:         s_req[s_req_tail].arg  = arg;
243:         s_req_tail = (uint8_t)((s_req_tail + 1U) % AUDIO_FIFO_MAX);
244:         s_req_cnt++;
245:     }
246:     else
247:     {
248:         /* 队列满时覆盖最旧的一条，保证最新指令发出 */
249:         s_req[s_req_head].type = type;
250:         s_req[s_req_head].arg  = arg;
251:         s_req_head = (uint8_t)((s_req_head + 1U) % AUDIO_FIFO_MAX);
252:         s_req_tail = s_req_head;
253:     }
254:     taskEXIT_CRITICAL();
255: }
