125: void Algo_Breath_FeedSample(uint16_t raw_adc, uint32_t now_ms)
126: {
127:     float raw = (float)raw_adc;
128:     float ac;
129:     float k_recent; /* Rising slope after valley */
130:     float k_prev;   /* Falling slope into valley */
131:     float valley_val;
132:     float th;
133:     uint32_t n;
134: 
135:     s_now_ms = now_ms;
136:     if (s_sample_cnt == 0U)
137:     {
138:         s_baseline = raw;
139:     }
140:     /* 关键修复（问题2）：基线跟踪时间常数放缓至约10秒（50Hz下系数 0.002），防止将真实人体的慢呼吸信号作为漂移滤除 */
141:     s_baseline = 0.998f * s_baseline + 0.002f * raw;
142:     ac = raw - s_baseline;
143:     s_lpf = 0.85f * s_lpf + 0.15f * ac;
144: 
145:     /* 当检测到有效呼吸扰动幅度 (>= 25.0f) 或已成功检测到波谷时，刷新信号活跃时间戳 */
146:     if (s_sample_cnt >= 25U && (fabsf(s_lpf) >= VALLEY_AMP_MIN_THRESH || s_cbpm_total > 0U))
147:     {
148:         s_last_signal_ms = now_ms;
149:     }
150: 
151:     s_buf[s_sample_cnt % BREATH_BUF_LEN] = s_lpf;
152:     s_sample_cnt++;
153:     if (s_sample_cnt < 9U) return;
154: 
155:     n = s_sample_cnt;
156:     /* PDF eq: averaged 1st-order differences around candidate valley fmin at (n-5) */
157:     k_recent = (s_buf[(n - 1U) % BREATH_BUF_LEN] + s_buf[(n - 2U) % BREATH_BUF_LEN]
158:               - s_buf[(n - 3U) % BREATH_BUF_LEN] - s_buf[(n - 4U) % BREATH_BUF_LEN]) * 0.5f;
159:     k_prev   = (s_buf[(n - 5U) % BREATH_BUF_LEN] + s_buf[(n - 6U) % BREATH_BUF_LEN]
160:               - s_buf[(n - 7U) % BREATH_BUF_LEN] - s_buf[(n - 8U) % BREATH_BUF_LEN]) * 0.5f;
161: 
162:     valley_val = s_buf[(n - 5U) % BREATH_BUF_LEN];
163:     s_amp_env = 0.98f * s_amp_env + 0.02f * fabsf(s_lpf);
164:     th = s_amp_env * 0.25f;
165:     if (th < VALLEY_AMP_MIN_THRESH) th = VALLEY_AMP_MIN_THRESH;
166: 
167:     /* Valid valley: falling before (k_prev < 0), rising after (k_recent > 0), and below negative threshold */
168:     if (k_prev < 0.0f && k_recent > 0.0f && valley_val < -th)
169:     {
170:         on_valid_valley(now_ms);
171:     }
172: }
